<?php if ($canViewAnalytics): $reportMax = max(1, max(array_column($adminReportActivity, 'sessions') ?: [0])); ?>
<section class="panel"><div class="section-heading"><div><h2>Báo cáo hoạt động nhóm</h2><p>Chọn kỳ thống kê để xem xu hướng tập luyện</p></div><form method="get" action="<?= sf_h(url('admin')) ?>#reports" class="admin-member-edit-form"><select name="admin_period" aria-label="Kỳ thống kê"><?php foreach (['week'=>'Tuần này','month'=>'Tháng này','all'=>'Toàn thời gian'] as $key=>$label): ?><option value="<?= sf_h($key) ?>" <?= $adminReportPeriod===$key?'selected':'' ?>><?= sf_h($label) ?></option><?php endforeach; ?></select><button class="btn secondary">Xem</button></form></div>
<div class="admin-overview-grid"><div><h3>Buổi tập hoàn thành</h3><div class="admin-report-chart"><div class="admin-chart <?= $adminReportPeriod === 'month' ? 'admin-chart-dense' : '' ?>"><?php foreach ($adminReportActivity as $day): ?><div class="admin-chart-day" title="<?= sf_h($day['label']) ?>: <?= (int)$day['sessions'] ?> buổi"><span><?= (int)$day['sessions'] ?></span><i style="height:<?= max(3,(int)round((int)$day['sessions']/$reportMax*125)) ?>px"></i><small><?= sf_h($day['label']) ?></small></div><?php endforeach; ?></div></div><div class="admin-chart-legend"><i></i><?= $adminReportPeriod==='all'?'12 tháng gần nhất có buổi tập':'Số buổi hợp lệ theo ngày' ?></div></div>
<div><h3>Chỉ số nổi bật</h3><dl class="admin-summary-list"><div><dt>Buổi tập hoàn thành</dt><dd><?= number_format((int)$adminReportSummary['sessions']) ?></dd></div><div><dt>Tổng thời lượng</dt><dd><?= number_format((int)$adminReportSummary['seconds']/3600,1,',','.') ?> giờ</dd></div><div><dt>Thành viên có hoạt động</dt><dd><?= (int)$adminReportSummary['members'] ?></dd></div><div><dt>Chuỗi hiện tại dài nhất*</dt><dd><?= (int)$adminReportSummary['longest_streak'] ?> tuần</dd></div></dl><p class="muted" style="margin-top:16px">* Trong số thành viên có buổi tập ở kỳ đã chọn.</p></div></div>
</section>
<?php endif; ?>

<?php if ($canViewAnalytics): ?><section class="panel admin-page-panel"><div class="section-heading"><div><h2>Điểm tuần đã chốt</h2><p class="muted">Tối đa 50 bản ghi gần nhất.</p></div></div><?php foreach ($adminScores as $scoreRow): ?><div class="admin-member-row"><span><?= sf_h($scoreRow['display_name']) ?> · <?= sf_h($scoreRow['week_start']) ?> · <?= (int)$scoreRow['valid_sessions'] ?>/<?= (int)$scoreRow['target_sessions'] ?> buổi</span><b><?= (int)$scoreRow['total_week_points'] ?> điểm</b></div><?php endforeach; ?><?php if (!$adminScores): ?><p class="empty-inline">Chưa có điểm tuần để hiển thị.</p><?php endif; ?></section><?php endif; ?>

