<?php if ($canViewCron): ?><section class="panel admin-page-panel"><div class="section-heading"><div><h2>Lịch sử tác vụ nền</h2><p class="muted">Chạy lại tác vụ từ terminal trên máy chủ.</p></div></div><p><code>php cron/streakfit_maintenance.php</code></p><?php foreach ($cronRuns as $run): ?><div class="admin-member-row"><span><?= sf_h($run['task_name']) ?> · <?= sf_h($run['status']) ?><small><?= sf_h($run['started_at']) ?><?= $run['finished_at'] ? ' → ' . sf_h($run['finished_at']) : '' ?></small><?php if ($run['summary']): ?><small><?= sf_h($run['summary']) ?></small><?php endif; ?></span></div><?php endforeach; ?><?php if (!$cronRuns): ?><p class="empty-inline">Chưa có lần chạy tác vụ nào.</p><?php endif; ?></section><?php endif; ?>
